const src = $json.body ?? $json;

const itemType =
  src.item_type ??
  src.nomenclature_type ??
  src.type ??
  src['ВидНоменклатуры'] ??
  src['Вид номенклатуры'];

const name =
  src.name ??
  src.product_name ??
  src['Наименование'] ??
  src['Наименование товара'];

let imageBase64 =
  src.image_base64 ??
  src.image ??
  src['Картинка'] ??
  src['Изображение'];

let imageMime =
  src.image_mime ??
  src.mime_type ??
  src['ТипКартинки'] ??
  'image/jpeg';

const requestedCount =
  src.image_count ??
  src.count ??
  src['КоличествоКартинок'] ??
  src['Количество картинок'] ??
  3;

if (!itemType) throw new Error('Не передан item_type / ВидНоменклатуры');
if (!name) throw new Error('Не передан name / Наименование');
if (!imageBase64) throw new Error('Не передан image_base64 / Картинка');

const imageCount = Math.max(1, Math.min(10, Number(requestedCount) || 3));

if (String(imageBase64).startsWith('data:')) {
  const match = String(imageBase64).match(/^data:([^;]+);base64,(.+)$/s);
  if (!match) throw new Error('Некорректный data URL изображения');
  imageMime = match[1];
  imageBase64 = match[2];
}

imageBase64 = String(imageBase64).replace(/\s+/g, '');
const imageDataUrl = `data:${imageMime};base64,${imageBase64}`;

// Создаём binary-свойство sourceImage.
// AI Agent с passthroughBinaryImages увидит исходное изображение.
return [{
  json: {
    item_type: String(itemType),
    name: String(name),
    image_count: imageCount,
    image_mime: String(imageMime),
    image_base64: imageBase64,
    image_data_url: imageDataUrl
  },
  binary: {
    sourceImage: {
      data: imageBase64,
      mimeType: String(imageMime),
      fileName: 'product-reference'
    }
  }
}];

const src = $json;

// Правила можно вынести в MongoDB/1С/Google Sheets.
// Здесь они оставлены внутри workflow, чтобы пример легко импортировался.
const catalog = {
  'обув': {
    descriptionRules: `
Ты создаёшь карточку обуви для e-commerce.
Акцент: внешний вид, силуэт, видимые материалы, подошва, посадка и сценарий использования.
Нельзя придумывать состав, технологии, водостойкость, размеры и другие характеристики,
если их нет во входных данных или их нельзя уверенно определить по фотографии.`,
    imageRules: `
Это обувь. Во всех сгенерированных изображениях строго сохраняй исходную модель:
силуэт, цвет, материал, подошву, шнуровку, логотипы и конструктивные детали.
Можно менять только фон, окружение, свет, композицию и ракурс.
Не добавляй текст, цены, водяные знаки и новые логотипы.`
  },

  'одеж': {
    descriptionRules: `
Ты создаёшь карточку одежды для e-commerce.
Акцент: фасон, визуальная фактура, цвет, стиль, посадка и варианты сочетания.
Не выдумывай состав ткани, размеры и функциональные свойства.`,
    imageRules: `
Это одежда. Строго сохраняй фасон, цвет, принт, фурнитуру и пропорции изделия.
Можно менять фон, модель подачи, окружение, свет и ракурс.
Не изменяй дизайн вещи и не добавляй надписи.`
  },

  'электрон': {
    descriptionRules: `
Ты создаёшь карточку электроники.
Опиши назначение, внешний вид и только видимые особенности.
Не придумывай мощность, ёмкость, интерфейсы, совместимость и другие технические параметры.`,
    imageRules: `
Это электроника. Строго сохраняй корпус, цвет, кнопки, разъёмы, экран,
маркировку, логотипы и пропорции исходного устройства.
Сделай премиальную технологичную предметную съёмку без дополнительного текста.`
  },

  'космет': {
    descriptionRules: `
Ты создаёшь карточку косметики.
Опиши упаковку, формат, визуальное позиционирование и назначение,
если оно очевидно из названия и фото. Не придумывай состав, лечебные эффекты
и клинические обещания.`,
    imageRules: `
Это косметический продукт. Строго сохраняй форму упаковки, цвет,
этикетку и бренд. Используй аккуратный beauty-свет и коммерческую композицию.
Не изменяй надписи на упаковке и не создавай новые.`
  },

  'default': {
    descriptionRules: `
Ты создаёшь карточку товара для маркетплейса.
Подготовь точное продающее описание по названию и фотографии.
Не выдумывай свойства и характеристики, которых нет во входных данных
или которые нельзя достоверно определить по изображению.`,
    imageRules: `
Создавай профессиональные e-commerce изображения именно исходного товара.
Максимально сохраняй форму, цвет, материалы, логотипы, маркировку и детали.
Разрешено менять фон, окружение, свет, композицию и ракурс.
Запрещено добавлять текст, цены, водяные знаки и новые логотипы.`
  }
};

const key = Object.keys(catalog)
  .filter(k => k !== 'default')
  .find(k => src.item_type.toLowerCase().includes(k));

const rules = catalog[key ?? 'default'];

return [{
  json: {
    ...src,
    description_rules: rules.descriptionRules.trim(),
    image_rules: rules.imageRules.trim(),
    agent_model: 'openai/gpt-5.4',
    image_model: 'openai/gpt-image-1',
    aspect_ratio: '1:1',
    quality: 'high'
  },
  binary: $binary
}];

parameters.text:
=Проанализируй товар и исходную фотографию.

Вид номенклатуры: {{ $json.item_type }}
Наименование: {{ $json.name }}
Требуемое количество изображений: {{ $json.image_count }}

Правила написания описания:
{{ $json.description_rules }}

Правила для будущих изображений:
{{ $json.image_rules }}

Верни JSON строго по заданной схеме.
Поле image_prompts должно содержать РОВНО {{ $json.image_count }} элементов.
Каждый image_prompt должен быть самостоятельным подробным заданием для image-to-image генерации.
Промты должны давать разные коммерческие сцены/ракурсы, но сохранять один и тот же исходный товар.

parameters.jsCode:
const source = $('Prompt Router').first().json;
const agent = $json.output ?? $json;

let result = agent;

if (typeof result === 'string') {
  let text = result.trim();
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  result = JSON.parse(text);
}

const prompts = Array.isArray(result.image_prompts)
  ? result.image_prompts.filter(Boolean).map(String)
  : [];

const fallbackScenes = [
  'чистый каталожный кадр на светлом нейтральном фоне, мягкий студийный свет',
  'премиальный hero-shot, выразительный студийный свет и аккуратная глубина сцены',
  'естественная lifestyle-сцена в контексте использования товара',
  'альтернативный коммерческий ракурс, подчёркивающий форму и материалы',
  'крупный план ключевых визуальных деталей товара',
  'минималистичная рекламная композиция для маркетплейса'
];

while (prompts.length < source.image_count) {
  const scene = fallbackScenes[prompts.length % fallbackScenes.length];
  prompts.push(
    `${source.image_rules}\n\nСоздай ${scene}. ` +
    `Используй исходное изображение как строгий визуальный референс.`
  );
}

const exactPrompts = prompts.slice(0, source.image_count);

return [{
  json: {
    item_type: source.item_type,
    name: source.name,
    image_count: source.image_count,
    image_model: source.image_model,
    aspect_ratio: source.aspect_ratio,
    quality: source.quality,
    image_data_url: source.image_data_url,

    short_title: String(result.short_title ?? source.name),
    description: String(result.description ?? ''),
    selling_points: Array.isArray(result.selling_points)
      ? result.selling_points.map(String).slice(0, 5)
      : [],
    image_prompts: exactPrompts
  }
}];

const src = $json;

return src.image_prompts.map((prompt, index) => ({
  json: {
    index: index + 1,
    name: src.name,
    item_type: src.item_type,
    short_title: src.short_title,
    description: src.description,
    selling_points: src.selling_points,
    model: src.image_model,
    aspect_ratio: src.aspect_ratio,
    quality: src.quality,
    image_data_url: src.image_data_url,
    prompt
  }
}));

const source = $('Normalize Agent Output').first().json;
const generated = $input.all();

const images = generated.map((item, idx) => {
  const data = item.json?.data ?? [];
  const first = data[0];

  if (!first?.b64_json) {
    return {
      index: idx + 1,
      success: false,
      error: 'В ответе OpenRouter нет data[0].b64_json',
      raw: item.json
    };
  }

  return {
    index: idx + 1,
    success: true,
    media_type: first.media_type ?? 'image/png',
    base64: first.b64_json
  };
});

return [{
  json: {
    success: images.every(x => x.success),
    item_type: source.item_type,
    name: source.name,
    short_title: source.short_title,
    description: source.description,
    selling_points: source.selling_points,
    requested_images_count: source.image_count,
    generated_images_count: images.filter(x => x.success).length,
    images
  }
}];
